-- name: cli-subcommand-pattern-entities-v2
-- params: 
SELECT e.id AS entity_id, e.display AS display, e.mention_count AS mention_count, e.description AS description FROM Entity e
WHERE substr(e.description, 1, length('Cluster anchored on')) = 'Cluster anchored on' AND (substr(e.id, 1, length('debug-')) = 'debug-' OR substr(e.id, 1, length('init-')) = 'init-' OR substr(e.id, 1, length('train-')) = 'train-' OR substr(e.id, 1, length('validate-')) = 'validate-' OR substr(e.id, 1, length('convert-')) = 'convert-' OR substr(e.id, 1, length('apply-')) = 'apply-' OR substr(e.id, 1, length('package-')) = 'package-' OR substr(e.id, 1, length('assemble-')) = 'assemble-' OR substr(e.id, 1, length('evaluate-')) = 'evaluate-' OR substr(e.id, 1, length('run-')) = 'run-' OR substr(e.id, 1, length('build-')) = 'build-' OR substr(e.id, 1, length('deploy-')) = 'deploy-' OR substr(e.id, 1, length('benchmark-')) = 'benchmark-' OR substr(e.id, 1, length('profile-')) = 'profile-' OR substr(e.id, 1, length('serve-')) = 'serve-' OR substr(e.id, 1, length('show-')) = 'show-' OR substr(e.id, 1, length('list-')) = 'list-' OR substr(e.id, 1, length('check-')) = 'check-' OR substr(e.id, 1, length('info-')) = 'info-' OR substr(e.id, 1, length('find-')) = 'find-' OR substr(e.id, 1, length('clean-')) = 'clean-' OR substr(e.id, 1, length('install-')) = 'install-' OR substr(e.id, 1, length('update-')) = 'update-') ORDER BY e.id LIMIT 50;
